/*! WordPress i18n */
(function() {
  window.wp = window.wp || {};
  var localeData = {};

  window.wp.i18n = {
    setLocaleData: function(data, domain) {
      domain = domain || 'default';
      localeData[domain] = Object.assign(localeData[domain] || {}, data);
    },
    getLocaleData: function(domain) {
      domain = domain || 'default';
      return localeData[domain] || {};
    },
    __: function(text, domain) { return text; },
    _x: function(text, context, domain) { return text; },
    _n: function(single, plural, number, domain) { return number === 1 ? single : plural; },
    _nx: function(single, plural, number, context, domain) { return number === 1 ? single : plural; },
    isRTL: function() { return false; },
    sprintf: function(format) {
      var args = Array.prototype.slice.call(arguments, 1);
      var i = 0;
      return (format || '').replace(/%s|%d/g, function() {
        return args[i++] !== undefined ? args[i - 1] : '';
      });
    }
  };
})();
